import React, { useState, useEffect, useRef } from 'react';
import EnhancedDraggableWidget from '../EnhancedDraggableWidget';
import './SearchWidget.css';

const SearchWidget = ({ onClose, isVisible = true }) => {
  const [input, setInput] = useState('');
  const [result, setResult] = useState('Ready to search...');
  const [activeTab, setActiveTab] = useState('current'); // 'current' or 'history'
  const [isLoading, setIsLoading] = useState(false);
  const [searchHistory, setSearchHistory] = useState([]);
  const [angleMode, setAngleMode] = useState('deg'); // 'deg' or 'rad'
  const [widgetPos, setWidgetPos] = useState({ x: 0, y: 0 });
  const [widgetSize, setWidgetSize] = useState({ width: 550, height: 600 });
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const lastAnswer = useRef(0);

  const widgetRef = useRef(null);
  const resizeStartRef = useRef({ x: 0, y: 0, width: 0, height: 0 });

  // Initialize widget position
  useEffect(() => {
    setWidgetPos({
      x: window.innerWidth / 2 - 275, // Centered with width of 550
      y: window.innerHeight * 0.15
    });

    // Load search history from localStorage
    const savedHistory = localStorage.getItem('astra_search_history');
    if (savedHistory) {
      try {
        setSearchHistory(JSON.parse(savedHistory));
      } catch (e) {
        console.error('Error loading search history:', e);
        setSearchHistory([]);
      }
    }
  }, []);

  // Dragging functionality
  useEffect(() => {
    if (!isDragging) return;

    const handleMouseMove = (e) => {
      setWidgetPos({
        x: e.clientX - dragOffset.x,
        y: e.clientY - dragOffset.y,
      });
    };

    const handleMouseUp = () => {
      setIsDragging(false);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, dragOffset]);

  // Resizing functionality
  useEffect(() => {
    if (!isResizing) return;

    const handleMouseMove = (e) => {
      const newWidth = Math.max(400, resizeStartRef.current.width + (e.clientX - resizeStartRef.current.x));
      const newHeight = Math.max(500, resizeStartRef.current.height + (e.clientY - resizeStartRef.current.y));

      setWidgetSize({
        width: newWidth,
        height: newHeight,
      });
    };

    const handleMouseUp = () => {
      setIsResizing(false);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isResizing]);

  // Function to update search content
  const updateSearchContent = async (text) => {
    setIsLoading(true);

    try {
      // Simulate processing time for visual feedback
      await new Promise(resolve => setTimeout(resolve, 300));

      setResult(text);

      // Add to search history
      const newHistoryItem = {
        id: Date.now(),
        query: text.substring(0, 30) + (text.length > 30 ? '...' : ''), // Generate a title/summary
        result: text,
        timestamp: new Date().toISOString(),
        date: new Date().toLocaleString()
      };

      const updatedHistory = [newHistoryItem, ...searchHistory].slice(0, 50); // Keep last 50 searches
      setSearchHistory(updatedHistory);
      localStorage.setItem('astra_search_history', JSON.stringify(updatedHistory));
    } catch (error) {
      console.error('Error updating search content:', error);
      setResult('Error displaying search results');
    } finally {
      setIsLoading(false);
    }
  };

  // Function to switch tabs
  const switchTab = (tabName) => {
    setActiveTab(tabName);
  };

  // Function to view a history item
  const viewHistoryItem = (item) => {
    setResult(item.result);
    setInput(item.query);
    setActiveTab('current');
  };

  // Function to clear search history
  const clearHistory = () => {
    setSearchHistory([]);
    localStorage.removeItem('astra_search_history');
  };

  // Function to copy search content to clipboard
  const copyToClipboard = async () => {
    try {
      await navigator.clipboard.writeText(result);
      // Optionally show a notification that text was copied
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  // Function to set angle mode
  const setAngleModeHandler = (mode) => {
    setAngleMode(mode);
  };

  // Function to increase widget size
  const increaseWidgetSize = () => {
    setWidgetSize(prev => ({
      width: prev.width + 100,
      height: prev.height + 100
    }));
  };

  // Function to decrease widget size
  const decreaseWidgetSize = () => {
    setWidgetSize(prev => ({
      width: Math.max(400, prev.width - 100), // Minimum width of 400
      height: Math.max(500, prev.height - 100) // Minimum height of 500
    }));
  };

  // Handler for starting drag
  const handleDragStart = (e) => {
    if (e.target.closest('.widget-controls') ||
      e.target.closest('.resize-handle') ||
      e.target.closest('input') ||
      e.target.closest('button') ||
      e.target.closest('.tab-button')) return;

    setIsDragging(true);
    setDragOffset({
      x: e.clientX - widgetPos.x,
      y: e.clientY - widgetPos.y,
    });
  };

  // Handler for starting resize
  const handleResizeStart = (e) => {
    e.preventDefault();
    setIsResizing(true);
    resizeStartRef.current = {
      x: e.clientX,
      y: e.clientY,
      width: widgetSize.width,
      height: widgetSize.height,
    };
  };

  // Keyboard Event Listener
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (!isVisible) return;
      const key = e.key;

      if (/[0-9]/.test(key)) setInput(prev => prev + key);
      if (['+', '-', '*', '/', '.', '(', ')'].includes(key)) setInput(prev => prev + key);
      if (key === 'Enter') updateSearchContent(input);
      if (key === 'Backspace') setInput(prev => prev.slice(0, -1));
      if (key === 'Escape') { setInput(''); setResult('Ready to search...'); }
      if (key === 'a' || key === 'A') setInput(prev => prev + 'A');
      if (key === 'b' || key === 'B') setInput(prev => prev + 'B');
      if (key === 'c' || key === 'C') setInput(prev => prev + 'C');
      if (key === 'd' || key === 'D') setInput(prev => prev + 'D');
      if (key === 'e' || key === 'E') setInput(prev => prev + 'E');
      if (key === 'f' || key === 'F') setInput(prev => prev + 'F');
      if (key === 'g' || key === 'G') setInput(prev => prev + 'G');
      if (key === 'h' || key === 'H') setInput(prev => prev + 'H');
      if (key === 'i' || key === 'I') setInput(prev => prev + 'I');
      if (key === 'j' || key === 'J') setInput(prev => prev + 'J');
      if (key === 'k' || key === 'K') setInput(prev => prev + 'K');
      if (key === 'l' || key === 'L') setInput(prev => prev + 'L');
      if (key === 'm' || key === 'M') setInput(prev => prev + 'M');
      if (key === 'n' || key === 'N') setInput(prev => prev + 'N');
      if (key === 'o' || key === 'O') setInput(prev => prev + 'O');
      if (key === 'p' || key === 'P') setInput(prev => prev + 'P');
      if (key === 'q' || key === 'Q') setInput(prev => prev + 'Q');
      if (key === 'r' || key === 'R') setInput(prev => prev + 'R');
      if (key === 's' || key === 'S') setInput(prev => prev + 'S');
      if (key === 't' || key === 'T') setInput(prev => prev + 'T');
      if (key === 'u' || key === 'U') setInput(prev => prev + 'U');
      if (key === 'v' || key === 'V') setInput(prev => prev + 'V');
      if (key === 'w' || key === 'W') setInput(prev => prev + 'W');
      if (key === 'x' || key === 'X') setInput(prev => prev + 'X');
      if (key === 'y' || key === 'Y') setInput(prev => prev + 'Y');
      if (key === 'z' || key === 'Z') setInput(prev => prev + 'Z');
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [input, isVisible]);

  if (!isVisible) return null;

  return (
    <EnhancedDraggableWidget
      id="searchWidget"
      className="search-widget"
      title="NOVA SEARCH"
      initialSize={{ width: 550, height: 600 }}
      minSize={{ width: 400, height: 500 }}
      onClose={onClose}
      isVisible={isVisible}
    >
      <div className="corner-top-right"></div>
      <div className="corner-bottom-left"></div>
      <div className="widget-controls">
        <div className="widget-control-btn" onClick={increaseWidgetSize} title="Make Bigger">⧨</div>
        <div className="widget-control-btn" onClick={decreaseWidgetSize} title="Make Smaller">⧩</div>
        <div className="widget-control-btn" onClick={onClose} title="Close">⧬</div>
      </div>
      <div className="resize-handle"></div>
      <div className="search-wrapper">
        {/* Header */}
        <div className="search-label">
          SEARCH
        </div>

        {/* Display Screen */}
        <div className="search-screen-area">
          {isLoading ? (
            <div className="search-loading show">Searching...</div>
          ) : (
            <>
              <div className="search-input">{input}</div>
              <div className={`search-result ${result === 'Error' ? 'error' : ''}`}>{result}</div>
            </>
          )}
        </div>

        {/* Tab Controls */}
        <div className="controls-section">
          <div className="search-nav">
            <div
              className={`search-nav-tab ${activeTab === 'current' ? 'active' : ''}`}
              onClick={(e) => { e.stopPropagation(); switchTab('current'); }}
            >
              Current
            </div>
            <div
              className={`search-nav-tab ${activeTab === 'history' ? 'active' : ''}`}
              onClick={(e) => { e.stopPropagation(); switchTab('history'); }}
            >
              History
            </div>
          </div>
        </div>

        {/* Content Area */}
        <div className="button-section">
          {activeTab === 'current' ? (
            <div className="search-current-view">
              {result ? (
                <div className="search-content">
                  {result}
                </div>
              ) : (
                <div className="search-placeholder">
                  Ready to search...
                </div>
              )}
              {result && !isLoading && (
                <button className="copy-button" onClick={copyToClipboard} title="Copy search results">
                  <i className="fas fa-copy"></i>
                </button>
              )}
            </div>
          ) : (
            <div className="search-history-view">
              {searchHistory.length > 0 ? (
                <>
                  <div className="search-history-controls" style={{ marginBottom: '10px', textAlign: 'right' }}>
                    <button
                      className="search-clear-history-btn"
                      onClick={clearHistory}
                      style={{
                        background: 'linear-gradient(135deg, rgba(255, 80, 80, 0.9) 0%, rgba(255, 50, 50, 0.9) 100%)',
                        border: '1px solid rgba(255, 30, 30, 0.7)',
                        color: 'white',
                        padding: '4px 8px',
                        borderRadius: '4px',
                        fontSize: '10px',
                        cursor: 'pointer'
                      }}
                    >
                      Clear History
                    </button>
                  </div>
                  <div className="search-history">
                    {searchHistory.map(item => (
                      <div
                        key={item.id}
                        className="search-history-item"
                        onClick={() => viewHistoryItem(item)}
                      >
                        <div className="search-history-query">{item.query}</div>
                        <div className="search-history-date">{item.date}</div>
                        <div className="search-history-preview">
                          {item.result.length > 100 ? item.result.substring(0, 100) + '...' : item.result}
                        </div>
                      </div>
                    ))}
                  </div>
                </>
              ) : (
                <div className="search-history-empty">
                  No search history yet
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </EnhancedDraggableWidget>
  );
};

export default SearchWidget;
